import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';

// Navbar Component
const Navbar = () => (
  <nav className="bg-white shadow-lg sticky top-0 z-50">
    <div className="max-w-6xl mx-auto px-4">
      <div className="flex justify-between items-center h-16">
        {/* Logo & Name */}
        <div className="flex items-center space-x-2">
          <span className="text-3xl">🍕</span> 
          <span className="font-extrabold text-2xl text-orange-600 tracking-tight">PrestoPizza</span>
        </div>

        {/* Links */}
        <div className="hidden md:flex items-center space-x-8 font-medium text-gray-700">
          <Link title="Accueil" to="/" className="hover:text-orange-600 transition">Accueil</Link>
          <Link title="Menu" to="/menu" className="hover:text-orange-600 transition">Menu</Link>
          <Link title="Panier" to="/panier" className="relative hover:text-orange-600 transition">
            Panier
            <span className="absolute -top-2 -right-3 bg-orange-600 text-white text-xs rounded-full px-1.5">0</span>
          </Link>
          <Link title="Connexion" to="/login" className="bg-orange-600 text-white px-5 py-2 rounded-full hover:bg-orange-700 transition">
            Connexion
          </Link>
        </div>
      </div>
    </div>
  </nav>
);

// Menu Page Component
const Menu = ({ categories }) => (
  <div className="max-w-6xl mx-auto p-6">
    <h2 className="text-3xl font-bold text-gray-800 mb-8 border-b-2 border-orange-500 inline-block">Notre Menu</h2>
    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
      {categories.map(cat => (
        cat.dishes.map(dish => (
          <div key={dish.id} className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-xl transition duration-300">
            <div className="h-48 bg-orange-50 flex items-center justify-center text-5xl">
              {cat.name.toLowerCase().includes('pizza') ? '🍕' : '🍔'}
            </div>
            <div className="p-5">
              <div className="flex justify-between items-start mb-2">
                <h3 className="text-xl font-bold text-gray-800">{dish.name}</h3>
                <span className="text-orange-600 font-bold bg-orange-50 px-2 py-1 rounded-lg text-sm">{dish.price} DH</span>
              </div>
              <p className="text-gray-500 text-sm mb-4">Catégorie: {cat.name}</p>
              <button className="w-full bg-gray-900 text-white py-2.5 rounded-xl font-semibold hover:bg-orange-600 transition duration-300">
                Ajouter au panier
              </button>
            </div>
          </div>
        ))
      ))}
    </div>
  </div>
);

function App() {
  const [categories, setCategories] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(err => console.log(err));
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-gray-50 text-gray-900">
        <Navbar />

        <Routes>
          <Route path="/" element={
            <div className="text-center py-20 bg-white">
              <h1 className="text-5xl font-black text-gray-900 mb-4">Bienvenue chez <span className="text-orange-600">PrestoPizza</span></h1>
              <p className="text-xl text-gray-600">Découvrez les meilleures saveurs italiennes avec une touche marocaine.</p>
              <Link to="/menu" className="inline-block mt-8 bg-orange-600 text-white px-8 py-3 rounded-full font-bold text-lg hover:shadow-lg transition">Voir le Menu</Link>
            </div>
          } />
          <Route path="/menu" element={<Menu categories={categories} />} />
          <Route path="/panier" element={<div className="text-center py-20 text-2xl font-bold">Votre panier est vide 🛒</div>} />
          <Route path="/login" element={<div className="text-center py-20 text-2xl font-bold">Page de connexion 🔐</div>} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
